// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SalesOrderItem) predicate.SalesOrderItem {
	return predicate.SalesOrderItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SalesOrderItem) predicate.SalesOrderItem {
	return predicate.SalesOrderItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SalesOrderItem) predicate.SalesOrderItem {
	return predicate.SalesOrderItem(sql.NotPredicates(p))
}
